test('renderInvoiceText shows VAT above total line', () => {
  const invoice = {
    number: 'INV-2024-0001',
    customerId: 'C-001',
    issueDate: '2024-10-15',
    status: 'issued',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 10, unitPrice: 8500, vatRate: 21 },
    ],
  };

  const customer = { id: 'C-001', name: 'Acme Corp', email: 'hello@acme.example' };

  const text = renderInvoiceText(invoice, customer);
  const lines = text.split('\n');

  const vatLineIndex = lines.findIndex(l => l.startsWith('VAT:'));
  const totalLineIndex = lines.findIndex(l => l.startsWith('Total:'));

  assert.ok(vatLineIndex > -1, 'VAT line should exist');
  assert.ok(totalLineIndex > -1, 'Total line should exist');
  assert.ok(vatLineIndex < totalLineIndex, 'VAT line should be before total line');
});

