test('invoiceTotals sums VAT from multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 100, unitPrice: 1000, vatRate: 21 }, // 21000 VAT
      { qty: 100, unitPrice: 1000, vatRate: 9 },  // 9000 VAT
      { qty: 100, unitPrice: 1000, vatRate: 0 },  // 0 VAT
    ],
  };

  const totals = invoiceTotals(invoice);
