test('invoiceTotals works with real invoice from createInvoice', () => {
  const result = createInvoice({
    customerId: 'C-002', // Blue Fern Bakery is standard (0% discount)
    issueDate: '2024-10-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 10 },
    ],
  });

  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  const expectedSubtotal = 5 * 8500 + 10 * 9500;
  assert.equal(totals.subtotal, expectedSubtotal);
  assert.equal(totals.discount, 0); // standard tier has no discount
  // DES-HOUR and DEV-HOUR both have 21% VAT
  // VAT = (42500 * 21/100) + (95000 * 21/100) = 8925 + 19950 = 28875
  assert.equal(totals.vat, 28875);
  // total = subtotal - discount + vat = 137500 - 0 + 28875 = 166375
  assert.equal(totals.total, expectedSubtotal + totals.vat);
});

