});

test('lineVAT calculates VAT as (lineTotal - lineDiscount) × vatRate / 100', () => {
  const line = { qty: 100, unitPrice: 1000, vatRate: 21 };
  const vat = lineVAT(line);
  assert.equal(vat, 21000); // 100000 * 21 / 100
});

test('lineVAT returns 0 for VAT exempt products', () => {
  const line = { qty: 100, unitPrice: 1000, vatRate: 0 };
  const vat = lineVAT(line);
  assert.equal(vat, 0);
});

test('lineVAT accounts for discounts', () => {
  const line = { qty: 100, unitPrice: 1000, discountPercent: 10, vatRate: 21 };
  const vat = lineVAT(line);
  // lineTotal = 100000, discount = 10000, taxable = 90000
  // vat = 90000 * 21 / 100 = 18900
  assert.equal(vat, 18900);
});

test('lineVAT handles different VAT rates', () => {
  const line21 = { qty: 100, unitPrice: 1000, vatRate: 21 };
  const line9 = { qty: 100, unitPrice: 1000, vatRate: 9 };
  const line0 = { qty: 100, unitPrice: 1000, vatRate: 0 };

  assert.equal(lineVAT(line21), 21000);
  assert.equal(lineVAT(line9), 9000);
  assert.equal(lineVAT(line0), 0);
});

test('invoiceTotals includes vat in total', () => {
  const invoice = {
    lines: [{ qty: 100, unitPrice: 1000, vatRate: 21 }],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 100000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 21000);
  assert.equal(totals.total, 121000);
});

test('invoiceTotals sums VAT from multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 100, unitPrice: 1000, vatRate: 21 }, // 21000 VAT
      { qty: 100, unitPrice: 1000, vatRate: 9 },  // 9000 VAT
      { qty: 100, unitPrice: 1000, vatRate: 0 },  // 0 VAT
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 300000);
  assert.equal(totals.vat, 30000); // 21000 + 9000 + 0
  assert.equal(totals.total, 330000);
});

test('invoiceTotals with discount and VAT', () => {
  const invoice = {
    lines: [{ qty: 100, unitPrice: 1000, discountPercent: 10, vatRate: 21 }],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 100000);
  assert.equal(totals.discount, 10000); // 100000 * 10 / 100
  assert.equal(totals.vat, 18900); // (100000 - 10000) * 21 / 100
  assert.equal(totals.total, 108900); // 100000 - 10000 + 18900
});

test('invoiceTotals with multiple lines, discounts and different VAT rates', () => {
  const invoice = {
    lines: [
      { qty: 100, unitPrice: 1000, discountPercent: 5, vatRate: 21 },  // subtotal 100000, discount 5000, vat (95000*21/100)=19950
      { qty: 100, unitPrice: 1000, discountPercent: 10, vatRate: 9 },  // subtotal 100000, discount 10000, vat (90000*9/100)=8100
      { qty: 100, unitPrice: 1000, vatRate: 0 },                       // subtotal 100000, discount 0, vat 0
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 300000);
  assert.equal(totals.discount, 15000);
  assert.equal(totals.vat, 28050); // 19950 + 8100 + 0
  assert.equal(totals.total, 313050); // 300000 - 15000 + 28050
});

test('lineVAT rounds per line', () => {
  // A calculation that would result in a fraction of a cent
  const line = { qty: 1, unitPrice: 1000, vatRate: 21 };
  const vat = lineVAT(line);
  // 1000 * 21 / 100 = 210 (exact, no rounding needed)
  assert.equal(vat, 210);

  // Test with a value that creates a fraction
  const line2 = { qty: 1, unitPrice: 1, discountPercent: 33, vatRate: 21 };
  // lineTotal = 1, discount = 0.33, taxable = 0.67
  // vat = 0.67 * 21 / 100 = 0.1407
  // Should round to 0 (banker's rounding)
  const vat2 = lineVAT(line2);
  assert.equal(typeof vat2, 'number');
  assert.ok(vat2 >= 0);
});
